html:
{#- Horizon tax invoice (A4, email / PDF). Helpers: horizon_erp/printing.py -#}
{%- set reg = hml_company_registration(doc.company, doc.company_gstin) -%}
{%- set due = hml_payment_due_date(doc) -%}
{%- set disc = hml_total_discount_pct(doc) -%}
{%- set outstanding = hml_customer_outstanding(doc.customer, doc.company) -%}
<style>
	.hml { font-family: Helvetica, Arial, sans-serif; font-size: 10.5px; color: #222; }
	.hml h1 { font-size: 18px; margin: 0; letter-spacing: .5px; }
	.hml table { width: 100%; border-collapse: collapse; }
	.hml .grid td, .hml .grid th { border: 1px solid #bbb; padding: 4px 5px; vertical-align: top; }
	.hml .grid th { background: #f1f4f8; text-align: left; }
	.hml .r { text-align: right; }
	.hml .muted { color: #666; }
	.hml .high { background: #fff3cd; }
	.hml .flag { color: #b45309; font-weight: bold; }
	.hml .box { border: 1px solid #bbb; padding: 6px; }
	.hml .footer { margin-top: 10px; border-top: 2px solid #2e6bc6; padding-top: 6px; font-size: 9.5px; }
</style>
<div class="hml">
	<table><tr>
		<td style="width:60%">
			<h1>{{ doc.company }}</h1>
			<div class="muted">{{ reg.address.address_line1 }}{% if reg.address.address_line2 %}, {{ reg.address.address_line2 }}{% endif %}, {{ reg.address.city }} {{ reg.address.pincode }}, {{ reg.address.state }}</div>
		</td>
		<td class="r">
			<h1>TAX INVOICE</h1>
			<div><b>{{ doc.name }}</b></div>
			<div>Date: {{ frappe.format(doc.posting_date, "Date") }}</div>
			<div>Payment due: <b>{{ frappe.format(due, "Date") }}</b></div>
		</td>
	</tr></table>
	<br>
	<table><tr>
		<td class="box" style="width:50%">
			<b>Bill to</b><br>{{ doc.customer_name }}<br>{{ doc.address_display or "" }}
			{% if doc.billing_address_gstin %}<br>GSTIN: <b>{{ doc.billing_address_gstin }}</b>{% else %}<br>Unregistered{% endif %}
			<br>Place of supply: {{ doc.place_of_supply }}
		</td>
		<td class="box">
			{% if doc.po_no %}Customer PO: {{ doc.po_no }}<br>{% endif %}
			{% set so = doc.items[0].sales_order %}{% if so %}Sales Order: {{ so }}<br>{% endif %}
			{% set dn = doc.items[0].delivery_note %}{% if dn %}Delivery Note: {{ dn }}<br>{% endif %}
			Payment terms: {{ doc.payment_terms_template or "As per due date" }}<br>
			<b>Account outstanding (incl. this invoice): {{ frappe.format(outstanding, {"fieldtype": "Currency"}) }}</b>
			{% set limit = frappe.db.get_value("Customer Credit Limit", {"parent": doc.customer, "company": doc.company}, "credit_limit") %}
			{% if limit %}<br><span class="muted">Credit limit {{ frappe.format(limit, {"fieldtype": "Currency"}) }}{% if outstanding > limit %} - <span class="flag">over limit</span>{% endif %}</span>{% endif %}
		</td>
	</tr></table>
	<br>
	<table class="grid">
		<tr><th>#</th><th>Item</th><th>HSN</th><th class="r">Qty</th><th class="r">List Rate</th><th class="r">Disc %</th><th class="r">Rate</th><th class="r">Taxable</th></tr>
		{%- for row in doc.items %}
		<tr class="{{ 'high' if row.base_net_amount > 50000 else '' }}">
			<td>{{ row.idx }}</td>
			<td>{{ row.item_name }}{% if row.base_net_amount > 50000 %} <span class="flag">&#9888; high value</span>{% endif %}
				{% if row.serial_no %}<br><span class="muted">S/N: {{ row.serial_no | replace("\n", ", ") }}</span>{% endif %}
				{% if row.batch_no %}<br><span class="muted">Batch: {{ row.batch_no }}</span>{% endif %}</td>
			<td>{{ row.gst_hsn_code or "" }}</td>
			<td class="r">{{ row.get_formatted("qty") }} {{ row.uom }}</td>
			<td class="r">{{ row.get_formatted("price_list_rate") }}</td>
			<td class="r">{{ "%.2f"|format(row.discount_percentage or 0) }}</td>
			<td class="r">{{ row.get_formatted("rate") }}</td>
			<td class="r">{{ row.get_formatted("net_amount") }}</td>
		</tr>
		{%- endfor %}
	</table>
	<br>
	<table><tr>
		<td style="width:55%; vertical-align:top">
			<b>Total discount vs list price: {{ disc }} %</b><br>
			<span class="muted">Amount in words: {{ doc.in_words }}</span>
			{% set hint = hml_similar_in_stock(doc.items[0].item_code) %}
			{% if hint %}<br><br><b>Also available from stock:</b>
			{% for h in hint %}<br>&bull; {{ h.item_name }} ({{ h.qty | int }} in stock){% endfor %}{% endif %}
		</td>
		<td>
			<table class="grid">
				<tr><td>Taxable value</td><td class="r">{{ doc.get_formatted("net_total") }}</td></tr>
				{%- for t in doc.taxes if t.tax_amount %}
				<tr><td>{{ t.description }}</td><td class="r">{{ t.get_formatted("tax_amount") }}</td></tr>
				{%- endfor %}
				<tr><th>Grand total</th><th class="r">{{ doc.get_formatted("rounded_total") if doc.rounded_total else doc.get_formatted("grand_total") }}</th></tr>
			</table>
		</td>
	</tr></table>
	{% set terms = frappe.db.get_value("Company", doc.company, "hml_invoice_terms") %}
	{% if terms %}<div style="margin-top:8px"><b>Terms and conditions</b>{{ terms }}</div>{% endif %}
	<div class="footer">
		<b>{{ doc.company }}</b> &middot; GSTIN {{ doc.company_gstin or reg.address.gstin }} (State code {{ (doc.company_gstin or reg.address.gstin or "")[:2] }}) &middot; PAN {{ reg.pan }}
		&middot; Registered office: {{ reg.address.city }}, {{ reg.address.state }}<br>
		This is a computer-generated invoice. Subject to Mumbai jurisdiction. E&amp;OE.
	</div>
</div>
